import sqlite3
from dataclasses import dataclass

DB = "sensors.db"

@dataclass
class Reading:
    station: str
    day: str
    rainfall_mm: float

def load(path):
    con = sqlite3.connect(path)
    rows = con.execute("SELECT station, day, rainfall_mm FROM readings").fetchall()
    con.close()
    return [Reading(*row) for row in rows]

def wettest(readings, station):
    total = 0.0
    for r in readings:
        if r.station == station:
            total += r.rainfall_mm
    return total

if __name__ == "__main__":
    data = load(DB)
    for station in sorted({r.station for r in data}):
        print(station, wettest(data, station))

